// generate all subset sums modulo m for a given array
function genSums(arr) {
    const len = arr.length;
    const size = 1 << len;
    const sums = new Array(size);
    sums[0] = 0n;
    for (let mask = 1; mask < size; mask++) {
        const lsb = mask & -mask;
        const bit = Math.clz32(lsb) ^ 31; // index of least significant bit
        const prevMask = mask ^ lsb;
        sums[mask] = (sums[prevMask] + arr[bit]) % m;
    }
    return sums;
}

